back {\n  color: #ffffff;\n  font-size: 12px;\n  line-height: 1.55;\n}\n\n.overview-kicker {\n  display: block;\n  color: #76f4ff;\n  font-size: 10px;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\nh3,\np {\n  margin: 0;\n}\n\nh3 {\n  margin-top: 5px;\n  color: #eef2ff;\n  font-size: 18px;\n}\n\n.summary-overview p {\n  max-width: 540px;\n  margin-top: 8px;\n  color: #ffffff;\n  font-size: 13px;\n  line-height: 1.6;\n}\n\n.overview-stats {\n  display: flex;\n  flex: 0 0 auto;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 8px;\n}\n\n.overview-stats span,\n.floor-label,\n.current-label {\n  padding: 6px 10px;\n  border: 1px solid rgba(0, 229, 255, 0.18);\n  border-radius: 999px;\n  background: rgba(0, 229, 255, 0.08);\n  color: #76f4ff;\n  font-size: 11px;\n  white-space: nowrap;\n}\n\n.overview-stats strong {\n  color: #eef2ff;\n}\n\n.status-pill--muted {\n  border-color: rgba(255, 255, 255, 0.08) !important;\n  background: rgba(255, 255, 255, 0.03) !important;\n  color: #ffffff;\n}\n\n.tab-row {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n}\n\n.tab-button,\n.action-button {\n  border: 1px solid rgba(255, 255, 255, 0.09);\n  border-radius: 8px;\n  background: rgba(255, 255, 255, 0.03);\n  color: #ffffff;\n  cursor: pointer;\n  font: inherit;\n}\n\n.tab-button {\n  padding: 9px 14px;\n}\n\n.tab-button--active {\n  border-color: rgba(0, 229, 255, 0.34);\n  background: rgba(0, 229, 255, 0.1);\n  color: #76f4ff;\n}\n\n.summary-card {\n  padding: 14px;\n  border: 1px solid rgba(255, 255, 255, 0.06);\n  border-radius: 8px;\n  background: rgba(255, 255, 255, 0.025);\n}\n\n.summary-card header,\n.action-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.current-label {\n  border-color: rgba(168, 85, 247, 0.3);\n  background: rgba(168, 85, 247, 0.12);\n  color: #d8b4fe;\n}\n\n.summary-card p {\n  margin-top: 10px;\n  color: #ffffff;\n  line-height: 1.75;\n  white-space: pre-wrap;\n}\n\n.empty-state {\n  padding: 22px;\n  border: 1px dashed rgba(118, 244, 255, 0.18);\n  border-radius: 8px;\n  text-align: center;\n}\n\n.empty-state strong {\n  color: #dbe3ff;\n}\n\n.empty-state p {\n  margin-top: 8px;\n}\n\n.switch-row {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  padding: 12px;\n  border: 1px solid rgba(255, 255, 255, 0.06);\n  border-radius: 8px;\n  background: rgba(255, 255, 255, 0.025);\n  cursor: pointer;\n}\n\n.switch-row input {\n  width: 18px;\n  height: 18px;\n  margin: 2px 0 0;\n  accent-color: #00e5ff;\n}\n\n.switch-row strong,\n.switch-row small {\n  display: block;\n}\n\n.switch-row strong,\n.field > span {\n  color: #eef2ff;\n  font-size: 13px;\n}\n\n.switch-row small {\n  margin-top: 5px;\n}\n\n.form-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 12px;\n}\n\n.field {\n  display: flex;\n  flex-direction: column;\n  gap: 7px;\n}\n\n.field--full {\n  width: 100%;\n}\n\n.field input,\n.field textarea {\n  width: 100%;\n  box-sizing: border-box;\n  border: 1px solid rgba(118, 244, 255, 0.22);\n  border-radius: 8px;\n  background: rgba(11, 15, 32, 0.94);\n  color: #f7f9ff;\n  padding: 10px 12px;\n  font: inherit;\n}\n\n.field textarea {\n  min-height: 118px;\n  resize: vertical;\n}\n\n.field input:focus,\n.field textarea:focus {\n  outline: none;\n  border-color: rgba(118, 244, 255, 0.72);\n  box-shadow: 0 0 0 2px rgba(0, 229, 255, 0.1);\n}\n\n.action-row {\n  justify-content: flex-start;\n  flex-wrap: wrap;\n}\n\n.action-button {\n  padding: 10px 14px;\n}\n\n.action-button:hover {\n  border-color: rgba(0, 229, 255, 0.3);\n  background: rgba(0, 229, 255, 0.08);\n}\n\n.action-button--primary {\n  border-color: rgba(0, 229, 255, 0.34);\n  background: rgba(0, 229, 255, 0.13);\n  color: #76f4ff;\n}\n\n.feedback {\n  margin-left: 4px;\n}\n\n@media (max-width: 720px) {\n  .summary-overview,\n  .overview-stats {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n\n  .form-grid {\n    grid-template-columns: 1fr;\n  }\n}\n"],"sourceRoot":""}]);
